import{_ as i,a0 as o,w as t,s as d,ao as c,I as l,x as n,a1 as p,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 16 位系統上進行 64 位數學運算 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 16 位系統上進行 64 位數學運算 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 16 位系統上進行 64 位數學運算 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 16 位系統上進行 64 位數學運算 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20221026.0 ⭐️⭐️⭐️ Doing 64-bit math on a 16-bit system","title":"如何在 16 位系統上進行 64 位數學運算","tag":"202212","desc":""},"relativePath":"202212/20221026.0 ⭐️⭐️⭐️ Doing 64-bit math on a 16-bit system.md","filePath":"[post].md"}'),r={name:"202212/20221026.0 ⭐️⭐️⭐️ Doing 64-bit math on a 16-bit system.md"};function u(b,s,h,g,m,x){const a=o("Link");return t(),d("div",null,[s[15]||(s[15]=c(`<h1 id="如何在-16-位系統上進行-64-位數學運算" tabindex="-1">如何在 16 位系統上進行 64 位數學運算 <a class="header-anchor" href="#如何在-16-位系統上進行-64-位數學運算" aria-label="Permalink to “如何在 16 位系統上進行 64 位數學運算”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202212/09/150829g7c7x5e22qqo53c4.jpg" alt=""></p><blockquote><p>只要對彙編有一點基本的瞭解，這些函數就能擴展到任意位長的整型數學運算。</p></blockquote><p>幾年前，我為 FreeDOS 寫了一個叫做 VMATH 的命令列數學程序。它只能在很小的無符號整型上執行十分簡單的數學運算。隨着近來 FreeDOS 社區裏對基礎數學的興趣，我改進了 VMATH 使其可以為有符號 64 位整型提供基本的數學支持。</p><p>僅使用 16 位 8086 兼容的彙編指令來操控大型數字的過程並不簡單。我希望能夠分享一些在 VMATH 中用到的技術例子。其中一些方法掌握起來相當容易。而另外一些方法則看起來有點奇怪。你甚至可能學到一種進行基本數學運算的全新方式。</p><p>接下來要講的加、減、乘、除會用到的技術將不侷限於並不侷限於 64 位整型。只要對彙編有一點基本的瞭解，這些函數就能擴展到任意位長的整型數學運算。</p><p>在深入研究這些數學函數前，我想先從計算機的角度介紹一下數字的一些基本知識。</p><h3 id="計算機是如何讀取數字的" tabindex="-1">計算機是如何讀取數字的 <a class="header-anchor" href="#計算機是如何讀取數字的" aria-label="Permalink to “計算機是如何讀取數字的”">​</a></h3><p>一個英特爾兼容的 CPU 以<ruby>字節<rt>Byte</rt></ruby>的形式貯存數字，儲存順序為從最低有效字節到最高有效字節。每個字節由 8 個二進<ruby>位<rt>Bit</rt></ruby>組成，兩個字節組成一個<ruby>字<rt>Word</rt></ruby>。</p><p>一個儲存在內存裏的 64 位整型佔用了 8 個字節（即 4 個字）。例如，數字 <code>74565</code>（十六進制表示為 <code>0x12345</code>）的值長得是這個樣子的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>用字節表示：db 0x45, 0x23, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00</span></span>
<span class="line"><span>用字表示：dw 0x2345, 0x0001, 0x0000, 0x0000</span></span></code></pre></div><p>當讀取或寫入數據到內存時，CPU 會以正確的順序處理這些字節。對於比 8086 更現代的處理器而言，數據分組可以再大些，比如一個<ruby>四字組<rt>Quadword</rt></ruby>就可以表達整個 64 位整型 <code>0x0000000000012345</code>。</p><p>8086 CPU 不能理解這麼大的數字。當為 FreeDOS 編程時，你想要寫的是一個能在任意電腦上跑的程序，甚至是原始的 IBM PC 5150。你想要使用能夠擴展到任意大小整型的技術。我們其實並不關心更現代 CPU 的能力。</p><p>為了能做整型運算，我們的數據需要表達兩種不同類型的數字。</p><p>第一種是<ruby>無符號<rt>unsigned</rt></ruby>整型，其使用了所有的位來表達一個正數。無符號整型的值域為從 <code>0</code> 到 $2^{位長} - 1$。例如，8 位數可以是 <code>0</code> 到 <code>255</code> 之間的任意值，而 16 位數則在 <code>0</code> 到 <code>65535</code> 之間，以此類推。</p><p>有符號整型也很類似。不同之處在於數字的最高位代表了這個數是一個正數（<code>0</code>）還是一個負數 （<code>1</code>）。有符號整型的值域前半部分為正數，正數值域是從 <code>0</code> 到 $2^{(位長 - 1)} - 1$。整型值域的後半部分為負數，負數值域則從 $0 - (2^{位長 - 1})$ 到 <code>-1</code>。</p><p>比如説，一個 8 位數代表着 <code>0</code> 到 <code>127</code> 之間的任意正數，以及 <code>-128</code> 到 <code>-1</code> 之間的任意負數。為了能更好的理解這一點，想像 <strong>字節</strong> 為一列數組 <code>[0...127,-128...-1]</code>。因為 <code>-128</code> 在數組內緊跟着 <code>127</code>，<code>127</code> 加 <code>1</code> 等於 <code>-128</code>。當然這可能看起來有點奇怪甚至反常，但這其實讓這個層級的基本數學運算變簡單了。</p><p>為了能夠對大型整型進行簡單的加、減、乘、除，你應該摸索一些簡單的公式來計算一個數的絕對值或負值。你在做有符號整型運算的時候會用上它們的。</p><h3 id="絕對值與負值" tabindex="-1">絕對值與負值 <a class="header-anchor" href="#絕對值與負值" aria-label="Permalink to “絕對值與負值”">​</a></h3><p>計算一個有符號整型的絕對值並沒有它看起來的那麼糟糕。由於無符號和有符號數字在內存裏的儲存形式，我們其實有一個簡單的方案。你只需要翻轉一個負數的所有字位，得出的結果再加 <code>1</code>。</p><p>如果你從沒接觸過二進制的話，這可能聽上去有點奇怪，但這就是這麼工作的。讓我們來舉一個例子，取一個負數的 8 位表達，比如説 <code>-5</code>。因為 <code>-5</code> 靠近 <code>[0...127,-128...-1]</code> 字節組末端，它的十六進制值為 <code>0xfb</code>，二進制值為 <code>11111011</code>。如果你翻轉了所有字位，你會得到 <code>0x04</code> 或二進制值 <code>00000100</code>。結果加 <code>1</code> 你就得到了你的答案：你剛剛把 <code>-5</code> 的值變成了 <code>+5</code>。</p><p>你可以用匯編寫下這個程序用以返回任意 64 位數字的絕對值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>; 語法，NASM for DOS</span></span>
<span class="line"><span>proc_ABS:</span></span>
<span class="line"><span>  ; 啓動時，SI 寄存器會指向數據段（DS）內的內存位置，那裏存放着程序內包含着</span></span>
<span class="line"><span>  ; 會被轉為正數的 64 位數。</span></span>
<span class="line"><span>  ; 結束時，如果結果數字不能被轉正，CF 寄存器會被設置。這種情況只</span></span>
<span class="line"><span>  ; 有在遇到最大負值時會發生。其餘情況，CF 不會被設置。</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  ; 檢查最高字節的最高位</span></span>
<span class="line"><span>  test [si+7], byte 0x80</span></span>
<span class="line"><span>  ; 如不為 1，值為正值</span></span>
<span class="line"><span>  jz .done_ABS</span></span>
<span class="line"><span>  ; 翻轉所有位</span></span>
<span class="line"><span>  not word [si+6]       ; 字 #4</span></span>
<span class="line"><span>  not word [si+4]       ; 字 #3</span></span>
<span class="line"><span>  not word [si+2]       ; 字 #2</span></span>
<span class="line"><span>  not word [si]         ; 字 #1</span></span>
<span class="line"><span>  ; 字 #1 加 1</span></span>
<span class="line"><span>  inc word [si]</span></span>
<span class="line"><span>  ; 如結果不為 0，結束</span></span>
<span class="line"><span>  jnz .done_ABS</span></span>
<span class="line"><span>  ; 字 #2 加 1</span></span>
<span class="line"><span>  inc word [si+2]</span></span>
<span class="line"><span>  ; 如結果為 0，進位下一個字</span></span>
<span class="line"><span>  jnz .done_ABS</span></span>
<span class="line"><span>  inc word [si+4]</span></span>
<span class="line"><span>  jnz .done_ABS</span></span>
<span class="line"><span>  ; 此處無法進位</span></span>
<span class="line"><span>  inc word [si+6]</span></span>
<span class="line"><span>  ; 再一次檢查最高位</span></span>
<span class="line"><span>  test [si+7], byte 0x80</span></span>
<span class="line"><span>  ; 如不為 1，我們成功了，結束</span></span>
<span class="line"><span>  jz .done_ABS</span></span>
<span class="line"><span>  ; 溢出錯誤，它被轉成了負數</span></span>
<span class="line"><span>  stc</span></span>
<span class="line"><span>  ; 設置 CF 並返回</span></span>
<span class="line"><span>  ret</span></span>
<span class="line"><span>.done_ABS:</span></span>
<span class="line"><span>  ; 成功，清理 CF 並返回</span></span>
<span class="line"><span>  clc</span></span>
<span class="line"><span>  ret</span></span></code></pre></div><p>你可能已經注意到了，這個函數有一個潛在問題。由於正數和負數的二進制值表達方式，最大負數無法被轉成正數。以 8 位數為例，最大負數是 <code>-128</code>。如果你翻轉了 <code>-128</code> 的所有位數（二進制 <code>1__0000000</code>），你會得到 127（二進制 <code>0__1111111</code>）這個最大正值。如果你對結果加 <code>1</code>，它會因溢出回到同樣的負數（<code>-128</code>）。</p><p>要將正數轉成負數，你只需要重複計算絕對值的步驟就行。以下的程序十分相似，你唯一需要確認的就是一開始的數字不是已經負了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>; 語法， NASM for DOS</span></span>
<span class="line"><span>proc_NEG:</span></span>
<span class="line"><span>  ; 開始時，SI 會指向需要轉負的數字在內存裏的位置。</span></span>
<span class="line"><span>  ; 結束時，CF 永遠不會被設置。</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  ; 檢查最高字節的最高位</span></span>
<span class="line"><span>  test [si+7], byte 0x80</span></span>
<span class="line"><span>  ; 如為 1，數已經是負數</span></span>
<span class="line"><span>  jnz .done_NEG</span></span>
<span class="line"><span>  not word [si+6]       ; 翻轉字的所有位，字 #4</span></span>
<span class="line"><span>  not word [si+4]       ; 字 #3</span></span>
<span class="line"><span>  not word [si+2]       ; 字 #2</span></span>
<span class="line"><span>  not word [si]         ; 字 #1</span></span>
<span class="line"><span>  inc word [si]         ; 字 #1 加 1</span></span>
<span class="line"><span>  ; 如結果不為 0，結束</span></span>
<span class="line"><span>  jnz .done_NEG</span></span>
<span class="line"><span>  ; 字 #2 加 1</span></span>
<span class="line"><span>  inc word [si+2]</span></span>
<span class="line"><span>  ; 如結果為 0，進位下一個字</span></span>
<span class="line"><span>  jnz .done_NEG</span></span>
<span class="line"><span>  inc word [si+4]</span></span>
<span class="line"><span>  jnz .done_NEG</span></span>
<span class="line"><span>  ; 此處無法進位或轉化</span></span>
<span class="line"><span>  inc word [si+6]</span></span>
<span class="line"><span>  ; 正。</span></span>
<span class="line"><span>.done_NEG:</span></span>
<span class="line"><span>  clc                   ; 成功，清理 CF 並返回</span></span>
<span class="line"><span>  ret</span></span></code></pre></div><p>看着這些絕對值函數與負值函數間的通用代碼，它們應該被合併起來節約一些字節。合併代碼也會帶來額外的好處。首先，合併代碼能幫助防止簡單的筆誤。這樣也可以減少測試的要求。進一步來講，這樣通常會讓代碼變得簡單易懂。在閲讀一長串的彙編指令時，忘記讀到哪裏是常有的事。現在，我們可以不管這些。</p><p>計算一個數的絕對值或負值並不難。但是，這些函數對於我們即將開始的有符號整型數學運算至關重要。</p><p>我已經介紹了整型數字在位這一層面的基本表示方法，也創造了可以改變這些數字的基本程序，現在我們可以做點有趣的了。</p><p>讓我們來做些數學運算吧！</p><hr>`,31)),l("p",null,[s[1]||(s[1]=n("via: ",-1)),p(a,{href:"https://opensource.com/article/22/10/64-bit-math"},{default:e(()=>[...s[0]||(s[0]=[n("https://opensource.com/article/22/10/64-bit-math",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=n("作者：",-1)),p(a,{href:"https://opensource.com/users/shidel"},{default:e(()=>[...s[2]||(s[2]=[n("Jerome Shidel",-1)])]),_:1}),s[7]||(s[7]=n(" 選題：",-1)),p(a,{href:"https://github.com/lkxed"},{default:e(()=>[...s[3]||(s[3]=[n("lkxed",-1)])]),_:1}),s[8]||(s[8]=n(" 譯者：",-1)),p(a,{href:"https://github.com/yzuowei"},{default:e(()=>[...s[4]||(s[4]=[n("yzuowei",-1)])]),_:1}),s[9]||(s[9]=n(" 校對：",-1)),p(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=n("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原創編譯，",-1)),p(a,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[n("Linux中國",-1)])]),_:1}),s[14]||(s[14]=n(" 榮譽推出",-1))])])}const _=i(r,[["render",u]]);export{C as __pageData,_ as default};
